.sl-feature-tabs {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-feature-tabs h2,
.sl-feature-tabs .sl-tab-title {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-feature-tabs .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-feature-tabs .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-feature-tabs .sl-bg-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
}
.sl-feature-tabs .sl-border { border-color: var(--smartlearn-card-border); }
.sl-feature-tabs .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
}
.sl-feature-tabs .sl-tab-content-container {
    aspect-ratio: 4 / 3;
}
.sl-feature-tabs .sl-tab-btn {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    transition: border-color 0.25s ease, background-color 0.25s ease, box-shadow 0.25s ease;
    border: 2px solid transparent;
    cursor: pointer;
}
.sl-feature-tabs .sl-tab-btn:hover {
    border-color: var(--smartlearn-card-border);
    background-color: var(--smartlearn-card-bg);
}
.sl-feature-tabs .sl-tab-btn:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
.sl-feature-tabs .sl-tab-btn.active {
    border-color: var(--smartlearn-primary);
    background-color: var(--smartlearn-card-bg);
    box-shadow: 0 4px 16px color-mix(in srgb, var(--smartlearn-text) 8%, transparent);
}
.sl-feature-tabs .sl-tab-btn .sl-tab-icon {
    transition: color 0.25s ease;
    color: var(--smartlearn-text-muted);
}
.sl-feature-tabs .sl-tab-btn .sl-tab-title {
    transition: color 0.25s ease;
    color: var(--smartlearn-text);
    font-size: 1.25rem;
    line-height: 1.3;
}
.sl-feature-tabs .sl-tab-btn.active .sl-tab-icon,
.sl-feature-tabs .sl-tab-btn.active .sl-tab-title {
    color: var(--smartlearn-primary);
}
.sl-feature-tabs .sl-tab-pane {
    opacity: 0;
    transform: translateY(20px);
    transition: opacity 0.35s ease, transform 0.35s ease;
    pointer-events: none;
    z-index: 0;
}
.sl-feature-tabs .sl-tab-pane.active {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
    z-index: 1;
}
@media (prefers-reduced-motion: reduce) {
    .sl-feature-tabs .sl-tab-btn,
    .sl-feature-tabs .sl-tab-btn .sl-tab-icon,
    .sl-feature-tabs .sl-tab-btn .sl-tab-title,
    .sl-feature-tabs .sl-tab-pane {
        transition: none;
        transform: none;
    }
}

