(function() {
    function initTabs(root) {
        if (root.dataset.slInit === '1') return;
        root.dataset.slInit = '1';

        const btns = Array.from(root.querySelectorAll('.sl-tab-btn'));
        const panes = Array.from(root.querySelectorAll('.sl-tab-pane'));
        if (!btns.length || !panes.length) return;

        const uid = 'sl-tabs-' + Math.random().toString(36).slice(2, 8);
        btns.forEach((btn, idx) => {
            const pane = panes[idx];
            const tabId = uid + '-tab-' + idx;
            const paneId = uid + '-pane-' + idx;
            btn.id = tabId;
            btn.setAttribute('aria-controls', paneId);
            if (pane) {
                pane.id = paneId;
                pane.setAttribute('aria-labelledby', tabId);
            }
        });

        function activate(index) {
            btns.forEach((b, i) => {
                const active = i === index;
                b.classList.toggle('active', active);
                b.setAttribute('aria-selected', active ? 'true' : 'false');
                b.setAttribute('tabindex', active ? '0' : '-1');
            });
            panes.forEach((p, i) => {
                const active = i === index;
                p.classList.toggle('active', active);
                if (active) {
                    p.removeAttribute('hidden');
                } else {
                    p.setAttribute('hidden', '');
                }
            });
        }

        btns.forEach((btn, idx) => {
            btn.addEventListener('click', () => activate(idx));
            btn.addEventListener('keydown', (e) => {
                let next = -1;
                if (e.key === 'ArrowDown' || e.key === 'ArrowRight') next = (idx + 1) % btns.length;
                else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') next = (idx - 1 + btns.length) % btns.length;
                else if (e.key === 'Home') next = 0;
                else if (e.key === 'End') next = btns.length - 1;
                if (next !== -1) {
                    e.preventDefault();
                    activate(next);
                    btns[next].focus();
                }
            });
        });
    }

    function initAll() {
        document.querySelectorAll('.sl-feature-tabs').forEach(initTabs);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
